import os
import torch


class Config:
    """
    Configuration for Phase-Aware Stratified 1D Attention ResUNet.
    """

    # =========================================================================
    # File Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_27"

    # Metadata Files (Generated by previous steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Submission Output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Cache Directory for deterministic data processing
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")

    # =========================================================================
    # Data Preprocessing Parameters
    # =========================================================================
    RANDOM_SEED = 42

    # Time Alignment
    TIME_QUANTIZATION_SECONDS = 1  # Round timestamps to nearest second (1Hz)

    # Signal Stratification Criteria
    # Stratum 1: Global (All visible satellites)
    # Stratum 2: High-Precision (L5/E5a/B2a bands OR Valid Carrier Phase)
    # Stratum 3: High-Risk (Low Elevation)

    # High Precision Signal Types (Substrings to match in SignalType column)
    HIGH_PRECISION_BANDS = ["L5", "E5A", "B2A", "J5"]

    # AccumulatedDeltaRangeState Bitmask for Valid Carrier Phase
    # Bit 0 (Value 1) typically indicates Valid state in Android GNSS
    ADR_STATE_VALID_BIT = 1

    # Elevation Threshold for High Risk Stratum (Degrees)
    ELEVATION_HIGH_RISK_THRESHOLD = 30.0

    # Feature Engineering
    # Raw features to aggregate per stratum
    RAW_FEATURES = ["Cn0DbHz", "SvElevationDegrees"]

    # Aggregation statistics to compute for each raw feature in each stratum
    AGGREGATION_STATS = ["mean", "std", "min", "max"]

    # Geometric Context Features (Global)
    # Sine and Cosine of the Signal-Weighted Azimuth Centroid
    GEOMETRIC_FEATURES = ["AzimuthCentroidSin", "AzimuthCentroidCos"]

    # Input Channels Calculation:
    # 3 Strata * 2 Raw Features * 4 Stats = 24 channels
    # + 2 Geometric Context channels = 26 channels
    INPUT_CHANNELS = 26

    # Target Variables
    # Regression targets: Position offset in meters from WLS baseline (East, North)
    TARGET_COLUMNS = ["DeltaNorthMeters", "DeltaEastMeters"]
    OUTPUT_CHANNELS = 2

    # Sequence Length for Training
    # Fixed window size for batching during training.
    # Inference uses full drive length.
    TRAIN_SEQUENCE_LENGTH = 256

    # =========================================================================
    # Model Hyperparameters
    # =========================================================================
    MODEL_NAME = "PhaseAwareStratified1DAttentionResUNet"

    # Encoder Architecture (1D ResNet)
    # Number of filters at each encoder stage
    ENCODER_FILTERS = [32, 64, 128, 256]

    # Decoder Architecture
    # Number of filters at each decoder stage (symmetric to encoder)
    DECODER_FILTERS = [256, 128, 64, 32]

    # Attention Mechanism
    USE_ATTENTION_GATES = True

    # ASPP Bottleneck
    # Dilation rates for Atrous Spatial Pyramid Pooling
    ASPP_DILATIONS = [1, 6, 12, 18]

    # Deep Supervision
    # Enable auxiliary output heads at intermediate decoder layers
    USE_DEEP_SUPERVISION = True

    # =========================================================================
    # Training Configuration
    # =========================================================================
    BATCH_SIZE = 32
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    NUM_EPOCHS = 50
    EARLY_STOPPING_PATIENCE = 10

    # Loss Weights for Deep Supervision
    # [Final Output, Aux Head 1 (Coarser), Aux Head 2 (Coarsest)]
    # Aux heads operate on decimated targets.
    LOSS_WEIGHTS = [1.0, 0.5, 0.25]

    # Hardware
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    def __init__(self):
        """
        Initialize configuration and ensure necessary directories exist.
        """
        # Create directories for caching and outputs
        os.makedirs(self.WORKING_DIR, exist_ok=True)
        os.makedirs(self.CACHE_DIR, exist_ok=True)
        os.makedirs(self.SUBMISSION_DIR, exist_ok=True)

    def get_strata_names(self):
        """Returns the names of the defined strata."""
        return ["Global", "HighPrecision", "HighRisk"]

    def get_feature_names(self):
        """
        Generates the full list of input feature names based on strata and stats.
        """
        feature_names = []
        strata = self.get_strata_names()

        # Stratified Features
        for stratum in strata:
            for feat in self.RAW_FEATURES:
                for stat in self.AGGREGATION_STATS:
                    feature_names.append(f"{stratum}_{feat}_{stat}")

        # Geometric Context Features
        feature_names.extend(self.GEOMETRIC_FEATURES)

        return feature_names
